mapper.select:
SELECT s.id, u.username, s.device_info, s.ip_address, s.create_time, s.expire_time,
       FALSE AS is_current

AND u.username = #{username}
ORDER BY s.create_time DESC, s.id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE sys_session SET revoke_time = #{now}
WHERE id = #{sessionId} AND user_id = #{userId}
  AND revoke_time IS NULL AND expire_time > #{now}

UPDATE sys_session SET revoke_time = #{now}
WHERE id = #{sessionId} AND revoke_time IS NULL AND expire_time > #{now}

    AND NOT EXISTS (
        SELECT 1 FROM sys_user_role ur
        JOIN sys_role r ON r.id = ur.role_id
        WHERE ur.user_id = sys_session.user_id
          AND r.role_code = 'super_admin' AND r.status = 1
    )
